package io.fireflysoftware.experience.finance.terminal.web.owner;
import io.fireflysoftware.experience.finance.terminal.owner.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import org.springframework.test.web.reactive.server.WebTestClient;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import reactor.core.publisher.Mono;import java.util.*;import java.util.concurrent.atomic.*;
class BankOwnerDeskControllerTest{
 final UUID tenant=UUID.randomUUID(),bank=UUID.randomUUID(),enrollment=UUID.randomUUID();
 String path(){return "/api/v1/staff/tenants/"+tenant+"/banks/"+bank+"/enrollments/"+enrollment+"/versions/1/current";}
 @Test void actualStaffRouteMapsAllSelectorsAndReturnsNoStore(){var count=new AtomicInteger();var client=WebTestClient.bindToController(new BankOwnerDeskController(q->{count.incrementAndGet();assertEquals(tenant,q.tenantId());assertEquals(bank,q.bankId());assertEquals(enrollment,q.enrollmentId());return Mono.just(new StaffBankOwnerView(tenant,bank,enrollment,1,UUID.randomUUID(),UUID.randomUUID(),Set.of("ACCOUNTING_BOOK"),1,1,1,1,2000,1000));})).build();client.get().uri(path()).exchange().expectStatus().isOk().expectHeader().cacheControl(CacheControl.noStore()).expectBody().consumeWith(response->{try{var body=new com.fasterxml.jackson.databind.ObjectMapper().readTree(response.getResponseBody());assertEquals(tenant.toString(),body.get("tenantId").asText());assertEquals(1000,body.get("observationUntilEpochMillis").asLong());assertFalse(body.has("financialAdmission"));}catch(java.io.IOException error){throw new AssertionError(error);}});assertEquals(1,count.get());}
 @Test void domainSuspensionRemains409(){var client=WebTestClient.bindToController(new BankOwnerDeskController(q->Mono.error(new ResponseStatusException(HttpStatus.CONFLICT)))).build();client.get().uri(path()).exchange().expectStatus().isEqualTo(409);}
 @Test void invalidVersionCannotCallService(){var count=new AtomicInteger();var client=WebTestClient.bindToController(new BankOwnerDeskController(q->{count.incrementAndGet();return Mono.empty();})).build();client.get().uri(path().replace("/versions/1/","/versions/0/")).exchange().expectStatus().isBadRequest();assertEquals(0,count.get());}
}
